UPDATE `saved_commands` SET `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$ErrorActionPreference = ''Stop''\ntry {\n  # Windows PowerShell 5.1 runs on .NET Framework, which has no TickCount64; it then reads the\n  # last start from the System log (Kernel-General event 12) instead.\n  $ticks = [Environment]::TickCount64\n  if ($null -ne $ticks) {\n    $up = [TimeSpan]::FromMilliseconds($ticks)\n    $boot = (Get-Date) - $up\n  } else {\n    $started = Get-WinEvent -FilterHashtable @{ LogName = ''System''; ProviderName = ''Microsoft-Windows-Kernel-General''; Id = 12 } -MaxEvents 1\n    $boot = $started.TimeCreated\n    $up = (Get-Date) - $boot\n  }\n  \"Last boot: $($boot.ToString(''yyyy-MM-dd HH:mm:ss''))\"\n  \"Up: $($up.Days) days, $($up.Hours) hours, $($up.Minutes) minutes\"\n} catch {\n  [Console]::Error.WriteLine(\"Failed: $($_.Exception.Message)\")\n  exit 1\n}"},{"osFamily":"linux","shell":"sh","script":"set -e\nup=$(uptime -p 2>/dev/null || uptime)\nboot=$(uptime -s 2>/dev/null || who -b)\nload=$(cut -d '' '' -f 1-3 /proc/loadavg)\necho \"Uptime: $up\"\necho \"Last boot: $boot\"\necho \"Load (1, 5, 15 min): $load\""}]', `version` = `version` + 1, `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `id` = '00000000-0000-4000-8000-00000005c003' AND `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$os = Get-CimInstance Win32_OperatingSystem\n$up = (Get-Date) - $os.LastBootUpTime\n\"Last boot: $($os.LastBootUpTime)\"\n\"Up: $($up.Days) days, $($up.Hours) hours, $($up.Minutes) minutes\""},{"osFamily":"linux","shell":"sh","script":"echo \"Uptime: $(uptime -p 2>/dev/null || uptime)\"\necho \"Last boot: $(uptime -s 2>/dev/null || who -b)\"\necho \"Load (1, 5, 15 min): $(cut -d '' '' -f 1-3 /proc/loadavg)\""}]' AND `parameters` = '[]';--> statement-breakpoint
UPDATE `saved_commands` SET `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$ErrorActionPreference = ''Stop''\ntry {\n  $columns = ''Id'', ''ProcessName'',\n    @{ n = ''CPUSeconds''; e = { [math]::Round($_.CPU, 1) } },\n    @{ n = ''MemoryMB''; e = { [math]::Round($_.WorkingSet64 / 1MB) } }\n  ''Top by CPU time:''\n  Get-Process | Sort-Object CPU -Descending | Select-Object -First 10 $columns | Format-Table -AutoSize | Out-String -Width 200\n  ''Top by memory:''\n  Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 10 $columns | Format-Table -AutoSize | Out-String -Width 200\n} catch {\n  [Console]::Error.WriteLine(\"Failed: $($_.Exception.Message)\")\n  exit 1\n}"},{"osFamily":"linux","shell":"sh","script":"set -e\nby_cpu=$(ps -eo pid,user,pcpu,pmem,comm --sort=-pcpu)\nby_memory=$(ps -eo pid,user,pcpu,pmem,comm --sort=-pmem)\necho \"Top by CPU:\"\nprintf ''%s\\n'' \"$by_cpu\" | head -n 11\necho\necho \"Top by memory:\"\nprintf ''%s\\n'' \"$by_memory\" | head -n 11"}]', `version` = `version` + 1, `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `id` = '00000000-0000-4000-8000-00000005c004' AND `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$columns = ''Id'', ''ProcessName'',\n  @{ n = ''CPUSeconds''; e = { [math]::Round($_.CPU, 1) } },\n  @{ n = ''MemoryMB''; e = { [math]::Round($_.WorkingSet64 / 1MB) } }\n''Top by CPU time:''\nGet-Process | Sort-Object CPU -Descending | Select-Object -First 10 $columns | Format-Table -AutoSize | Out-String -Width 200\n''Top by memory:''\nGet-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 10 $columns | Format-Table -AutoSize | Out-String -Width 200"},{"osFamily":"linux","shell":"sh","script":"echo \"Top by CPU:\"\nps -eo pid,user,pcpu,pmem,comm --sort=-pcpu | head -n 11\necho\necho \"Top by memory:\"\nps -eo pid,user,pcpu,pmem,comm --sort=-pmem | head -n 11"}]' AND `parameters` = '[]';--> statement-breakpoint
