UPDATE `saved_commands` SET `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$ErrorActionPreference = ''Stop''\ntry {\n  $since = (Get-Date).AddHours(-[int]$env:BMUSTER_PARAM_HOURS)\n  try {\n    $events = Get-WinEvent -FilterHashtable @{ LogName = ''System'', ''Application''; Level = 1, 2; StartTime = $since } -MaxEvents 200\n  } catch {\n    # Get-WinEvent reports finding nothing as an error; that is the good answer here.\n    if ($_.FullyQualifiedErrorId -notlike ''NoMatchingEventsFound*'') { throw }\n    $events = @()\n  }\n  if (-not $events) {\n    \"No errors in the last $env:BMUSTER_PARAM_HOURS hours.\"\n  } else {\n    $events | Select-Object TimeCreated, LogName, ProviderName, Id,\n      @{ n = ''Message''; e = { ($_.Message -split [Environment]::NewLine)[0] } } |\n      Format-Table -AutoSize -Wrap | Out-String -Width 250\n  }\n} catch {\n  [Console]::Error.WriteLine(\"Failed: $($_.Exception.Message)\")\n  exit 1\n}"},{"osFamily":"linux","shell":"sh","script":"if command -v journalctl >/dev/null 2>&1; then\n  journalctl --no-pager --priority=err --since \"$BMUSTER_PARAM_HOURS hours ago\" --lines=200\nelse\n  echo \"No journalctl; showing the end of the system log.\"\n  tail -n 200 /var/log/messages 2>/dev/null || tail -n 200 /var/log/syslog\nfi"}]', `version` = `version` + 1, `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `id` = '00000000-0000-4000-8000-00000005c006' AND `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$since = (Get-Date).AddHours(-[int]$env:BMUSTER_PARAM_HOURS)\n$events = Get-WinEvent -FilterHashtable @{ LogName = ''System'', ''Application''; Level = 1, 2; StartTime = $since } -MaxEvents 200 -ErrorAction SilentlyContinue\nif (-not $events) {\n  \"No errors in the last $env:BMUSTER_PARAM_HOURS hours.\"\n} else {\n  $events | Select-Object TimeCreated, LogName, ProviderName, Id,\n    @{ n = ''Message''; e = { ($_.Message -split [Environment]::NewLine)[0] } } |\n    Format-Table -AutoSize -Wrap | Out-String -Width 250\n}"},{"osFamily":"linux","shell":"sh","script":"if command -v journalctl >/dev/null 2>&1; then\n  journalctl --no-pager --priority=err --since \"$BMUSTER_PARAM_HOURS hours ago\" | tail -n 200\nelse\n  echo \"No journalctl; showing the end of the system log.\"\n  tail -n 200 /var/log/messages 2>/dev/null || tail -n 200 /var/log/syslog\nfi"}]' AND `parameters` = '[{"kind":"number","name":"hours","label":"Hours","min":1,"max":72}]';--> statement-breakpoint
UPDATE `saved_commands` SET `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$ErrorActionPreference = ''Stop''\ntry {\n  $interfaces = [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces() |\n    Where-Object { $_.OperationalStatus -eq ''Up'' -and $_.NetworkInterfaceType -ne ''Loopback'' }\n  foreach ($interface in $interfaces) {\n    $ip = $interface.GetIPProperties()\n    $v4 = $ip.UnicastAddresses | Where-Object { $_.Address.AddressFamily -eq ''InterNetwork'' } | ForEach-Object { $_.Address.ToString() }\n    $v6 = $ip.UnicastAddresses | Where-Object { $_.Address.AddressFamily -eq ''InterNetworkV6'' } | ForEach-Object { $_.Address.ToString() }\n    $gateways = $ip.GatewayAddresses | Where-Object { $_.Address.AddressFamily -eq ''InterNetwork'' } | ForEach-Object { $_.Address.ToString() }\n    $dns = $ip.DnsAddresses | ForEach-Object { $_.ToString() }\n    \"Interface: $($interface.Name)\"\n    \"  IPv4: $($v4 -join '', '')\"\n    \"  IPv6: $($v6 -join '', '')\"\n    \"  Gateway: $($gateways -join '', '')\"\n    \"  DNS: $($dns -join '', '')\"\n    ''''\n  }\n} catch {\n  [Console]::Error.WriteLine(\"Failed: $($_.Exception.Message)\")\n  exit 1\n}"},{"osFamily":"linux","shell":"sh","script":"set -e\necho \"Addresses:\"\nip -brief address 2>/dev/null || ip address\necho\necho \"Routes:\"\nip route\necho\necho \"DNS:\"\nif command -v resolvectl >/dev/null 2>&1 && resolvectl dns 2>/dev/null; then\n  :\nelse\n  grep -v ''^#'' /etc/resolv.conf || [ \"$?\" -eq 1 ]\nfi"}]', `version` = `version` + 1, `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `id` = '00000000-0000-4000-8000-00000005c007' AND `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"Get-NetIPConfiguration | ForEach-Object {\n  \"Interface: $($_.InterfaceAlias)\"\n  \"  IPv4: $(($_.IPv4Address | ForEach-Object IPAddress) -join '', '')\"\n  \"  IPv6: $(($_.IPv6Address | ForEach-Object IPAddress) -join '', '')\"\n  \"  Gateway: $(($_.IPv4DefaultGateway | ForEach-Object NextHop) -join '', '')\"\n  \"  DNS: $(($_.DNSServer | ForEach-Object ServerAddresses) -join '', '')\"\n  ''''\n}"},{"osFamily":"linux","shell":"sh","script":"echo \"Addresses:\"\nip -brief address 2>/dev/null || ip address\necho\necho \"Routes:\"\nip route\necho\necho \"DNS:\"\nif command -v resolvectl >/dev/null 2>&1 && resolvectl dns 2>/dev/null; then\n  :\nelse\n  grep -v ''^#'' /etc/resolv.conf\nfi"}]' AND `parameters` = '[]';--> statement-breakpoint
UPDATE `saved_commands` SET `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$ErrorActionPreference = ''Stop''\ntry {\n  $keys = ''HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*'',\n    ''HKLM:\\Software\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*''\n  # One broken uninstall entry, or no 32-bit list, should not stop the listing.\n  Get-ItemProperty $keys -ErrorAction SilentlyContinue | Where-Object DisplayName |\n    Sort-Object DisplayName -Unique |\n    Select-Object DisplayName, DisplayVersion, Publisher |\n    Format-Table -AutoSize | Out-String -Width 250\n} catch {\n  [Console]::Error.WriteLine(\"Failed: $($_.Exception.Message)\")\n  exit 1\n}"},{"osFamily":"linux","shell":"sh","script":"set -e\nif command -v dnf >/dev/null 2>&1 || command -v zypper >/dev/null 2>&1; then\n  packages=$(rpm -qa --qf ''%{NAME} %{VERSION}-%{RELEASE}\\n'')\nelif command -v apt-get >/dev/null 2>&1; then\n  packages=$(dpkg-query -W -f ''${Package} ${Version}\\n'')\nelse\n  echo \"No dnf, apt or zypper on this machine.\"\n  exit 1\nfi\nprintf ''%s\\n'' \"$packages\" | sort"}]', `version` = `version` + 1, `updated_at` = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE `id` = '00000000-0000-4000-8000-00000005c008' AND `scripts` = '[{"osFamily":"windows","shell":"powershell","script":"$keys = ''HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*'',\n  ''HKLM:\\Software\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*''\nGet-ItemProperty $keys -ErrorAction SilentlyContinue | Where-Object DisplayName |\n  Sort-Object DisplayName -Unique |\n  Select-Object DisplayName, DisplayVersion, Publisher |\n  Format-Table -AutoSize | Out-String -Width 250"},{"osFamily":"linux","shell":"sh","script":"if command -v dnf >/dev/null 2>&1 || command -v zypper >/dev/null 2>&1; then\n  rpm -qa --qf ''%{NAME} %{VERSION}-%{RELEASE}\\n'' | sort\nelif command -v apt-get >/dev/null 2>&1; then\n  dpkg-query -W -f ''${Package} ${